            إعادة المحاولة
          </Button>
        </div>
      ) : suppliers.length === 0 ? (
        <div className="p-12 text-center text-slate-500 bg-white rounded-md border border-slate-200">
          <Factory className="w-12 h-12 mx-auto text-slate-300 mb-3" />
          <h3 className="text-base font-bold text-slate-700">لا يوجد موردين</h3>
          <p className="text-xs text-slate-500 mt-1">
            أضف الموردين لربطهم بالأصناف وحساب جداول المزامنة
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {suppliers.map((sup) => (
            <Card
              key={sup.id}
              className="shadow-sm hover:shadow-sm transition-all cursor-pointer border-slate-200 flex flex-col justify-between"
              onClick={() => openSupplierDetail(sup.id)}
            >
              <CardHeader className="pb-3 border-b border-slate-100">
                <div className="flex items-start justify-between gap-2">
                  <div>
                    <CardTitle className="text-base font-bold text-[#0f172a] hover:text-[#c5a975] transition-colors">
                      {sup.name}
                    </CardTitle>
                    <Badge
                      variant="secondary"
                      className="text-[11px] mt-1.5 font-normal bg-blue-50 text-[#0f172a]"
                    >
                      {sup.specialization || "توريدات عامة"}
                    </Badge>
                  </div>
                  <div className="flex items-center gap-1" onClick={(e) => e.stopPropagation()}>
                    <Button variant="ghost" size="icon" onClick={() => openEditSupplier(sup)} className="h-8 w-8 text-slate-400 hover:text-emerald-600">
                      <Edit className="w-4 h-4" />
                    </Button>
                    <Button variant="ghost" size="icon" onClick={() => openDeleteSupplier(sup.id)} className="h-8 w-8 text-slate-400 hover:text-rose-600">
                      <Trash2 className="w-4 h-4" />
                    </Button>
                  </div>
                </div>
              </CardHeader>

              <CardContent className="pt-4 space-y-3 text-xs flex-1">
                {/* Ratings */}
                <div className="space-y-1.5 bg-slate-50 p-2.5 rounded-lg">
                  <div className="flex items-center justify-between">
                    <span className="text-slate-600">جودة التشطيب:</span>
                    {renderStars(sup.qualityRating)}
                  </div>
                  <div className="flex items-center justify-between">
                    <span className="text-slate-600">الالتزام بالمواعيد:</span>
                    {renderStars(sup.deliveryRating)}
                  </div>
                </div>

                {/* Contact Info */}
                <div className="space-y-1 text-slate-600">
                  {sup.contactPerson && (
                    <div className="flex items-center gap-1.5">
                      <User className="w-3.5 h-3.5 text-slate-400" />
                      <span>{sup.contactPerson}</span>
                    </div>
                  )}
                  <div className="flex items-center gap-1.5 font-semibold text-slate-800">
                    <Phone className="w-3.5 h-3.5 text-[#c5a975]" />
                    <span>{sup.phone}</span>
                  </div>
                  {sup.address && (
                    <div className="flex items-center gap-1.5 text-slate-500">
                      <MapPin className="w-3.5 h-3.5 text-slate-400" />
                      <span className="truncate">{sup.address}</span>
                    </div>
                  )}
                </div>

                {/* Active Orders Count & Stats */}
                <div className="pt-2 border-t border-slate-100 flex items-center justify-between">
                  <span className="text-slate-500">الأوامر النشطة حالياً:</span>
                  <Badge
                    variant={sup.activeOrdersCount > 0 ? "default" : "secondary"}
                    className={
                      sup.activeOrdersCount > 0
                        ? "bg-amber-600 text-white font-bold"
                        : "bg-slate-100 text-slate-600"
                    }
                  >
                    {sup.activeOrdersCount} أمر تصنيع
                  </Badge>
                </div>
              </CardContent>

              <CardFooter className="pt-2 pb-3 border-t border-slate-100 flex items-center justify-between bg-slate-50/50">
                <span className="text-[11px] text-slate-500">
                  منتجات الكتالوج: {sup._count?.catalogItems || 0}
                </span>
                <Button
                  size="sm"
                  variant="ghost"
                  className="text-xs text-[#0f172a] hover:text-[#c5a975] p-0 h-auto"
                >
                  عرض تفاصيل الأوامر
                  <Eye className="w-3.5 h-3.5 mr-1" />
                </Button>
              </CardFooter>
            </Card>
          ))}
        </div>
      )}

      {/* Supplier Orders Modal */}
      <Dialog open={isDetailOpen} onOpenChange={setIsDetailOpen}>
        <DialogContent className="max-w-3xl max-h-[85vh] overflow-y-auto">
          {loadingDetail ? (
            <div className="p-8 text-center text-slate-500">
              <RefreshCw className="w-8 h-8 animate-spin mx-auto text-[#0f172a] mb-2" />
              <p className="text-xs">جاري تحميل بيانات المصنع وأوامر التوريد...</p>
            </div>
          ) : selectedSupplier ? (
            <div className="space-y-4">
              <DialogHeader>
                <div className="flex items-center justify-between">
                  <div>
                    <DialogTitle className="text-lg font-black text-[#0f172a]">
                      {selectedSupplier.name}
                    </DialogTitle>
                    <DialogDescription className="text-xs">
                      {selectedSupplier.specialization} • هاتف: {selectedSupplier.phone}
                    </DialogDescription>
                  </div>
                  <Badge variant="outline" className="text-xs">
                    {selectedSupplier.supplierOrders?.length || 0} أوامر توريد مسجلة
                  </Badge>
                </div>
              </DialogHeader>

              {/* Financial summary for this supplier */}
              <div className="grid grid-cols-3 gap-3 p-3 bg-slate-50 rounded-lg text-center text-xs">
                <div>
                  <span className="text-slate-500 block">إجمالي التعاملات</span>
                  <span className="font-bold text-slate-900 text-sm mt-0.5 block">
                    {formatCurrency(
                      selectedSupplier.supplierOrders?.reduce(
                        (sum, o) => sum + o.totalAmount,
                        0
                      ) || 0
                    )}
                  </span>
                </div>
                <div className="border-r border-slate-200">
                  <span className="text-slate-500 block">المسدد للمورد</span>
                  <span className="font-bold text-emerald-700 text-sm mt-0.5 block">
                    {formatCurrency(
                      selectedSupplier.supplierOrders?.reduce(
                        (sum, o) => sum + o.amountPaid,
                        0
                      ) || 0
                    )}
                  </span>
                </div>
                <div className="border-r border-slate-200">
                  <span className="text-slate-500 block">المتبقي له</span>
                  <span className="font-bold text-amber-700 text-sm mt-0.5 block">
                    {formatCurrency(
                      (selectedSupplier.supplierOrders?.reduce(
                        (sum, o) => sum + o.totalAmount,
                        0
                      ) || 0) -
                        (selectedSupplier.supplierOrders?.reduce(
                          (sum, o) => sum + o.amountPaid,
                          0
                        ) || 0)
                    )}
                  </span>
                </div>
              </div>

              {/* Supplier Orders Table */}
              <div>
                <h4 className="text-xs font-bold text-[#0f172a] uppercase tracking-wider mb-2">
                  سجل أوامر التوريد للمشاريع
                </h4>
                {selectedSupplier.supplierOrders?.length === 0 ? (
                  <div className="p-6 text-center text-slate-400 text-xs border rounded-lg">
                    لا توجد أوامر توريد مسندة لهذا المصنع حالياً
                  </div>
                ) : (
                  <div className="border rounded-lg overflow-hidden">
                    <Table>
                      <TableHeader className="bg-slate-50 text-xs">
                        <TableRow>
                          <TableHead>المشروع / العميل</TableHead>
                          <TableHead>تاريخ الطلب</TableHead>
                          <TableHead>التسليم المتوقع</TableHead>
                          <TableHead className="text-left">القيمة</TableHead>
                          <TableHead className="text-center">الحالة</TableHead>
                        </TableRow>
                      </TableHeader>
                      <TableBody className="text-xs divide-y divide-slate-100">
                        {selectedSupplier.supplierOrders?.map((order) => (
                          <TableRow key={order.id}>
                            <TableCell>
                              <div className="font-bold text-slate-900">
                                {order.project.title}
                              </div>
                              <div className="text-[11px] text-slate-500">
                                العميل: {order.project.client.name}
                              </div>
                            </TableCell>
                            <TableCell>{formatDate(order.orderDate)}</TableCell>
                            <TableCell className="font-semibold text-amber-700">
                              {formatDate(order.expectedDate)}
                            </TableCell>
                            <TableCell className="text-left font-bold text-slate-900">
                              {formatCurrency(order.totalAmount)}
                            </TableCell>
                            <TableCell className="text-center">
                              <Badge
                                variant="secondary"
                                className={`text-[10px] ${getStatusColor(order.status)}`}
                              >
                                {getStatusLabel(order.status)}
                              </Badge>
                            </TableCell>
                          </TableRow>
                        ))}
                      </TableBody>
                    </Table>
                  </div>
                )}
              </div>

              <DialogFooter className="pt-2">
                <Button variant="outline" onClick={() => setIsDetailOpen(false)}>
                  إغلاق
                </Button>
              </DialogFooter>
            </div>
          ) : null}
        </DialogContent>
      </Dialog>
      <Dialog open={isDeleteOpen} onOpenChange={setIsDeleteOpen}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle className="text-lg font-bold text-[#0f172a]">
              ????? ??? ??????
            </DialogTitle>
            <DialogDescription className="text-rose-600">
              ?? ??? ????? ?? ??? ??? ??????? ???? ?????? ?? ????? ???????? ???? ????? ??????? ???????? ????????? ???????? ?????? ??????.
            </DialogDescription>
          </DialogHeader>
          <DialogFooter className="pt-2 gap-2 sm:justify-start">
            <Button
              variant="destructive"
              disabled={submitting}
              onClick={handleDeleteSupplier}
            >
              {submitting ? "???? ?????..." : "???? ???? ??????"}
            </Button>
            <Button
              type="button"
              variant="outline"
              onClick={() => setIsDeleteOpen(false)}
            >
              ?????
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { NextRequest, NextResponse } from 'next/server';
import prisma from '@/lib/db';
import { requireApiSession } from '@/lib/api-auth';

// POST /api/catalog/batch - Batch operations on catalog items
export async function POST(request: NextRequest) {
  const unauthorized = requireApiSession(request);
  if (unauthorized) return unauthorized;
  try {
    const body = await request.json();
    const { action, ids, categoryId } = body;

    if (!action || !ids || !Array.isArray(ids) || ids.length === 0) {
      return NextResponse.json(
        { error: 'action and ids[] are required' },
        { status: 400 }
      );
    }

    const numericIds = ids.map((id: any) => parseInt(String(id), 10)).filter((id: number) => !isNaN(id));

    switch (action) {
      case 'activate': {
        await prisma.catalogItem.updateMany({
          where: { id: { in: numericIds } },
          data: { isActive: true },
        });
        return NextResponse.json({ success: true, message: `تم تنشيط ${numericIds.length} منتج` });
      }

      case 'deactivate': {
        await prisma.catalogItem.updateMany({
          where: { id: { in: numericIds } },
          data: { isActive: false },
        });
        return NextResponse.json({ success: true, message: `تم تعطيل ${numericIds.length} منتج` });
      }

      case 'delete': {
        await prisma.catalogItem.updateMany({
          where: { id: { in: numericIds } },
          data: { isActive: false },
        });
        return NextResponse.json({ success: true, message: `تم حذف ${numericIds.length} منتج` });
      }

      case 'move': {
        if (!categoryId) {
          return NextResponse.json(
            { error: 'categoryId is required for move action' },
            { status: 400 }
          );
        }
        const targetCategoryId = parseInt(String(categoryId), 10);
        const category = await prisma.category.findUnique({ where: { id: targetCategoryId } });
        if (!category) {
          return NextResponse.json({ error: 'الفئة المستهدفة غير موجودة' }, { status: 404 });
        }

        await prisma.catalogItem.updateMany({
          where: { id: { in: numericIds } },
          data: { categoryId: targetCategoryId },
        });
        return NextResponse.json({
          success: true,
          message: `تم نقل ${numericIds.length} منتج إلى فئة "${category.nameAr}"`,
        });
      }

      case 'feature': {
        await prisma.catalogItem.updateMany({
          where: { id: { in: numericIds } },
          data: { isFeatured: true },
        });
        return NextResponse.json({ success: true, message: `تم تمييز ${numericIds.length} منتج` });
      }

      case 'unfeature': {
        await prisma.catalogItem.updateMany({
          where: { id: { in: numericIds } },
          data: { isFeatured: false },
        });
        return NextResponse.json({ success: true, message: `تم إزالة التمييز من ${numericIds.length} منتج` });
      }

      default:
        return NextResponse.json({ error: `Unknown action: ${action}` }, { status: 400 });
    }
  } catch (error: any) {
    console.error('Error in batch operation:', error);
    return NextResponse.json(
      { error: 'فشل في تنفيذ العملية', details: error.message },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import prisma from '@/lib/db';
import { requireApiSession } from '@/lib/api-auth';

// GET /api/projects - Fetch all projects with client relation
export async function GET(request: NextRequest) {
  const unauthorized = requireApiSession(request);
  if (unauthorized) return unauthorized;
  try {
    const { searchParams } = new URL(request.url);
    const status = searchParams.get('status');
    const type = searchParams.get('type');
    const priority = searchParams.get('priority');
    const search = searchParams.get('search');
    const clientId = searchParams.get('clientId');

    const whereClause: any = {};

    if (status) {
      whereClause.status = status;
    }

    if (type) {
      whereClause.type = type;
    }

    if (priority) {
      whereClause.priority = priority;
    }

    if (clientId) {
      whereClause.clientId = parseInt(clientId, 10);
    }

    if (search && search.trim() !== '') {
      const searchTerm = search.trim();
      whereClause.OR = [
        { title: { contains: searchTerm } },
        { notes: { contains: searchTerm } },
        { client: { name: { contains: searchTerm } } },
        { client: { phone: { contains: searchTerm } } },
        { client: { company: { contains: searchTerm } } },
      ];
    }

    const projects = await prisma.project.findMany({
      where: whereClause,
      include: {
        client: true,
        _count: {
          select: {
            items: true,
            tasks: true,
            supplierOrders: true,
            payments: true,
          },
        },
      },
      orderBy: { createdAt: 'desc' },
    });

    return NextResponse.json(projects);
  } catch (error: any) {
    console.error('Error fetching projects:', error);
    return NextResponse.json(
      { error: 'Failed to fetch projects', details: error.message },
      { status: 500 }
    );
  }
}

// POST /api/projects - Create new project with client
export async function POST(request: NextRequest) {
  const unauthorized = requireApiSession(request);
  if (unauthorized) return unauthorized;
  try {
    const body = await request.json();
    const {
      title,
      type,
      status,
      clientId,
      client, // Optional client object to create a new client { name, phone, email, company, address, notes }
      inspectionDate,
      designDeadline,
      approvalDate,
      estimatedDelivery,
      syncDate,
      totalCost,
      totalPrice,
      amountPaid,
      shippingCost,
      installationCost,
      notes,
      priority,
      items, // Optional array of items [{ catalogItemId, quantity, unitCost, unitPrice, notes, leadTimeDays }]
    } = body;

    if (!title) {
      return NextResponse.json(
        { error: 'Project title is required' },
        { status: 400 }
      );
    }

    let finalClientId = clientId ? parseInt(String(clientId), 10) : null;

    // If no existing clientId provided, create or find client from client object
    if (!finalClientId) {
      if (!client || !client.name || !client.phone) {
        return NextResponse.json(
          { error: 'Either clientId or client details (name and phone) must be provided' },
          { status: 400 }
        );
      }

      // Check if client with this phone already exists
      let existingClient = await prisma.client.findFirst({
        where: { phone: client.phone },
      });

      if (!existingClient) {
        existingClient = await prisma.client.create({
          data: {
            name: client.name,
            phone: client.phone,
            email: client.email || null,
            company: client.company || null,
            address: client.address || null,
            notes: client.notes || null,
          },
        });
      }

      finalClientId = existingClient.id;
    }

    // Process initial items if provided
    let calculatedCost = totalCost !== undefined ? parseFloat(String(totalCost)) : 0;
    let calculatedPrice = totalPrice !== undefined ? parseFloat(String(totalPrice)) : 0;

    let itemsData: any[] = [];
    if (Array.isArray(items) && items.length > 0) {
      for (const item of items) {
        const catalogItem = await prisma.catalogItem.findUnique({
          where: { id: parseInt(String(item.catalogItemId), 10) },
        });

        const qty = item.quantity ? parseInt(String(item.quantity), 10) : 1;
        const uCost = item.unitCost !== undefined ? parseFloat(String(item.unitCost)) : (catalogItem?.costPrice || 0);
        const uPrice = item.unitPrice !== undefined ? parseFloat(String(item.unitPrice)) : (catalogItem?.sellingPrice || 0);
        const leadDays = item.leadTimeDays !== undefined ? parseInt(String(item.leadTimeDays), 10) : (catalogItem?.leadTimeDays || 7);

        itemsData.push({
          catalogItemId: parseInt(String(item.catalogItemId), 10),
          quantity: qty,
          unitCost: uCost,
          unitPrice: uPrice,
          leadTimeDays: leadDays,
          notes: item.notes || null,
          status: 'PENDING',
        });
      }

      if (totalCost === undefined) {
        calculatedCost = itemsData.reduce((acc, curr) => acc + curr.quantity * curr.unitCost, 0);
      }
      if (totalPrice === undefined) {
        calculatedPrice = itemsData.reduce((acc, curr) => acc + curr.quantity * curr.unitPrice, 0);
      }
    }

    const newProject = await prisma.project.create({
      data: {
        clientId: finalClientId,
        title,
        type: type || 'LARGE_PROJECT',
        status: status || 'LEAD',
        inspectionDate: inspectionDate ? new Date(inspectionDate) : null,
        designDeadline: designDeadline ? new Date(designDeadline) : null,
        approvalDate: approvalDate ? new Date(approvalDate) : null,
        estimatedDelivery: estimatedDelivery ? new Date(estimatedDelivery) : null,
        syncDate: syncDate ? new Date(syncDate) : null,
        totalCost: calculatedCost,
        totalPrice: calculatedPrice,
        amountPaid: amountPaid !== undefined ? parseFloat(String(amountPaid)) : 0,
        shippingCost: shippingCost !== undefined ? parseFloat(String(shippingCost)) : 0,
        installationCost: installationCost !== undefined ? parseFloat(String(installationCost)) : 0,
        notes: notes || null,
        priority: priority || 'MEDIUM',
        ...(itemsData.length > 0 && {
          items: {
            create: itemsData,
          },
        }),
      },
      include: {
        client: true,
        items: {
          include: {
            catalogItem: true,
          },
        },
      },
    });

    return NextResponse.json(newProject, { status: 201 });
  } catch (error: any) {
    console.error('Error creating project:', error);
    return NextResponse.json(
      { error: 'Failed to create project', details: error.message },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import prisma from '@/lib/db';
import { requireApiSession } from '@/lib/api-auth';

// GET /api/quotes/[id] - Fetch single quote with items and catalog details
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const unauthorized = requireApiSession(request);
  if (unauthorized) return unauthorized;
  try {
    const { id } = await params;
    const quoteId = parseInt(id, 10);

    if (isNaN(quoteId)) {
      return NextResponse.json({ error: 'Invalid quote ID' }, { status: 400 });
    }

    const quote = await prisma.quoteRequest.findUnique({
      where: { id: quoteId },
      include: {
        items: {
          include: {
            catalogItem: {
              include: {
                category: true,
                supplier: true,
              },
            },
          },
        },
      },
    });

    if (!quote) {
      return NextResponse.json({ error: 'Quote request not found' }, { status: 404 });
    }

    return NextResponse.json(quote);
  } catch (error: any) {
    console.error('Error fetching quote request:', error);
    return NextResponse.json(
      { error: 'Failed to fetch quote request', details: error.message },
      { status: 500 }
    );
  }
}

// PUT /api/quotes/[id] - Update quote status or details
export async function PUT(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const unauthorized = requireApiSession(request);
  if (unauthorized) return unauthorized;
  try {
    const { id } = await params;
    const quoteId = parseInt(id, 10);

    if (isNaN(quoteId)) {
      return NextResponse.json({ error: 'Invalid quote ID' }, { status: 400 });
    }

    const existingQuote = await prisma.quoteRequest.findUnique({
      where: { id: quoteId },
    });

    if (!existingQuote) {
      return NextResponse.json({ error: 'Quote request not found' }, { status: 404 });
    }

    const body = await request.json();
    const {
      clientName,
      clientEmail,
      clientPhone,
      company,
      message,
      status,
      totalEstimate,
    } = body;

    const updatedQuote = await prisma.quoteRequest.update({
      where: { id: quoteId },
      data: {
        ...(clientName !== undefined && { clientName }),
        ...(clientEmail !== undefined && { clientEmail }),
        ...(clientPhone !== undefined && { clientPhone }),
        ...(company !== undefined && { company }),
        ...(message !== undefined && { message }),
        ...(status !== undefined && { status }),
        ...(totalEstimate !== undefined && { totalEstimate: parseFloat(String(totalEstimate)) }),
      },
      include: {
        items: {
          include: {
            catalogItem: {
              include: {
                category: true,
              },
            },
          },
        },
      },
    });

    return NextResponse.json(updatedQuote);
  } catch (error: any) {
    console.error('Error updating quote request:', error);
    return NextResponse.json(
      { error: 'Failed to update quote request', details: error.message },
      { status: 500 }
    );
  }
}

// DELETE /api/quotes/[id] - Delete quote
export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const unauthorized = requireApiSession(request);
  if (unauthorized) return unauthorized;
  try {
    const { id } = await params;
    const quoteId = parseInt(id, 10);

    if (isNaN(quoteId)) {
      return NextResponse.json({ error: 'Invalid quote ID' }, { status: 400 });
    }

    const existingQuote = await prisma.quoteRequest.findUnique({
      where: { id: quoteId },
    });

    if (!existingQuote) {
      return NextResponse.json({ error: 'Quote request not found' }, { status: 404 });
